import json
from typing import Any

import pandas as pd

from lfx.custom import Component
from lfx.io import BoolInput, DataFrameInput, IntInput, Output, StrInput
from lfx.schema import DataFrame, Message


class HoldoutDatasetBuilder(Component):
    display_name = "BAU Holdout Dataset Builder"
    description = "Selects a limited test sample and removes hidden ground-truth labels before classification."
    icon = "ListFilter"
    name = "HoldoutDatasetBuilder"

    inputs = [
        DataFrameInput(name="dataset", display_name="Generated Dataset", required=True),
        IntInput(name="sample_size", display_name="Tickets to Test", value=10),
        StrInput(name="id_field", display_name="Ticket ID Field", value="number"),
        StrInput(
            name="fields_to_hide",
            display_name="Additional Fields to Hide",
            value="category,subcategory,assignment_group",
            info="Comma-separated labels that must not be visible to the BAU agent. All _expected_* fields are always hidden.",
        ),
        StrInput(
            name="visible_fields",
            display_name="Fields Sent to BAU Agent",
            value="number,short_description,description,state,impact,urgency,priority,business_service",
            info="Comma-separated allow-list that limits prompt size. The ticket ID field is always retained.",
        ),
        BoolInput(name="random_sample", display_name="Random Sample", value=True),
        IntInput(name="random_seed", display_name="Random Seed", value=42, advanced=True),
    ]

    outputs = [
        Output(display_name="Visible Tickets", name="tickets", method="build_tickets"),
        Output(display_name="Hidden Ground Truth", name="ground_truth", method="build_ground_truth"),
        Output(display_name="Split Summary", name="summary", method="build_summary"),
    ]

    def _split(self) -> tuple[pd.DataFrame, pd.DataFrame, list[str]]:
        cached = getattr(self, "_split_cache", None)
        if cached is not None:
            return cached

        frame = pd.DataFrame(self.dataset).copy()
        if frame.empty:
            raise ValueError("Generated Dataset is empty.")
        size = min(max(int(self.sample_size), 1), len(frame))
        if self.random_sample and len(frame) > size:
            selected = frame.sample(n=size, random_state=int(self.random_seed)).reset_index(drop=True)
        else:
            selected = frame.head(size).reset_index(drop=True)

        id_field = str(self.id_field or "number").strip()
        if not id_field or id_field not in selected.columns or selected[id_field].duplicated().any():
            id_field = "_evaluation_id"
            selected[id_field] = [f"TEST-{index + 1:05d}" for index in range(len(selected))]
            self.id_field = id_field

        configured = {
            field.strip()
            for field in str(self.fields_to_hide or "").split(",")
            if field.strip()
        }
        hidden = sorted(
            column
            for column in selected.columns
            if str(column).startswith("_expected_") or column in configured
        )
        visible = selected.drop(columns=hidden, errors="ignore")
        allowed = [
            field.strip()
            for field in str(self.visible_fields or "").split(",")
            if field.strip()
        ]
        if allowed:
            retained = [column for column in [id_field, *allowed] if column in visible.columns]
            retained = list(dict.fromkeys(retained))
            visible = visible[retained]
        self._split_cache = (visible, selected, hidden)
        return self._split_cache

    def build_tickets(self) -> DataFrame:
        visible, _, _ = self._split()
        return DataFrame(visible)

    def build_ground_truth(self) -> DataFrame:
        _, ground_truth, _ = self._split()
        return DataFrame(ground_truth)

    def build_summary(self) -> Message:
        visible, _, hidden = self._split()
        return Message(
            text=(
                f"Prepared {len(visible)} holdout tickets. Hidden fields: "
                f"{json.dumps(hidden, ensure_ascii=False)}. Ticket ID field: {self.id_field}."
            )
        )

import json
import re
from typing import Any

import pandas as pd

from lfx.custom import Component
from lfx.io import DataFrameInput, Output, StrInput
from lfx.schema import Data, DataFrame, Message


class BAUEvaluator(Component):
    display_name = "Know Your BAU Evaluator"
    description = "Compares BAU predictions with hidden synthetic ground truth and calculates evaluation metrics."
    icon = "ChartNoAxesCombined"
    name = "BAUEvaluator"

    inputs = [
        DataFrameInput(name="ground_truth", display_name="Hidden Ground Truth", required=True),
        DataFrameInput(name="predictions", display_name="BAU Predictions", required=True),
        StrInput(name="id_field", display_name="Ticket ID Field", value="number"),
        StrInput(
            name="response_column",
            display_name="Batch Model Response Column",
            value="model_response",
            info="If prediction fields are not already columns, parse them from this JSON response column.",
            advanced=True,
        ),
        StrInput(
            name="target_fields",
            display_name="Fields to Score",
            value="category,ticket_type,required_skills,technology,support_level,assignment_group,agent_action",
        ),
        StrInput(
            name="breakdown_fields",
            display_name="Fields Preserved for Dashboard Breakdowns",
            value="_test_scenario,state,priority",
            info="Comma-separated ground-truth context fields copied into scored results but not used as prediction targets.",
        ),
    ]

    outputs = [
        Output(display_name="Scored Tickets", name="scored_tickets", method="build_scored_tickets"),
        Output(display_name="Resolution Decisions", name="resolution_decisions", method="build_resolution_decisions"),
        Output(display_name="Evaluation Metrics", name="metrics", method="build_metrics"),
        Output(display_name="Evaluation Summary", name="summary", method="build_summary"),
    ]

    @staticmethod
    def _normalize(value: Any) -> Any:
        if value is None or (isinstance(value, float) and pd.isna(value)):
            return None
        if isinstance(value, str):
            stripped = value.strip()
            if stripped.startswith("[") and stripped.endswith("]"):
                try:
                    return BAUEvaluator._normalize(json.loads(stripped))
                except json.JSONDecodeError:
                    pass
            return " ".join(stripped.casefold().split())
        if isinstance(value, (list, tuple, set)):
            normalized = [BAUEvaluator._normalize(item) for item in value]
            return sorted((item for item in normalized if item is not None), key=str)
        if isinstance(value, dict):
            return {key: BAUEvaluator._normalize(item) for key, item in sorted(value.items())}
        return value

    @staticmethod
    def _parse_model_response(value: Any) -> dict[str, Any]:
        if isinstance(value, dict):
            return value
        if not isinstance(value, str) or not value.strip():
            return {}
        cleaned = value.strip()
        fenced = re.fullmatch(r"```(?:json)?\s*(.*?)\s*```", cleaned, flags=re.DOTALL | re.IGNORECASE)
        if fenced:
            cleaned = fenced.group(1).strip()
        try:
            payload = json.loads(cleaned)
        except json.JSONDecodeError:
            start, end = cleaned.find("{"), cleaned.rfind("}")
            if start < 0 or end <= start:
                return {}
            try:
                payload = json.loads(cleaned[start : end + 1])
            except json.JSONDecodeError:
                return {}
        if not isinstance(payload, dict):
            return {}
        if isinstance(payload.get("prediction"), dict):
            payload = payload["prediction"]
        aliases = {
            "level": "support_level",
            "tier": "support_level",
            "support_tier": "support_level",
        }
        return {aliases.get(str(key), str(key)): item for key, item in payload.items()}

    def _evaluate(self) -> tuple[pd.DataFrame, dict[str, Any]]:
        cached = getattr(self, "_evaluation_cache", None)
        if cached is not None:
            return cached
        truth = pd.DataFrame(self.ground_truth).copy()
        predicted = pd.DataFrame(self.predictions).copy()
        if truth.empty:
            raise ValueError("Hidden Ground Truth is empty.")
        if predicted.empty:
            raise ValueError("BAU Predictions is empty.")
        id_field = str(self.id_field or "number").strip()
        if id_field not in truth.columns or id_field not in predicted.columns:
            if "_evaluation_id" in truth.columns and "_evaluation_id" in predicted.columns:
                id_field = "_evaluation_id"
                self.id_field = id_field
            else:
                raise ValueError(f"Ticket ID field '{id_field}' must exist in ground truth and predictions.")

        response_column = str(self.response_column or "model_response").strip()
        prediction_rows = []
        for source_row in predicted.to_dict(orient="records"):
            row = dict(source_row)
            parsed = self._parse_model_response(row.get(response_column))
            for key, value in parsed.items():
                row.setdefault(key, value)
            prediction_rows.append(row)
        predicted_by_id = {str(row[id_field]): row for row in prediction_rows}
        prediction_ids = set(predicted_by_id)
        truth = truth.loc[truth[id_field].map(str).isin(prediction_ids)].reset_index(drop=True)
        if truth.empty:
            raise ValueError("No prediction IDs match the Hidden Ground Truth dataset.")
        targets = [field.strip() for field in str(self.target_fields or "").split(",") if field.strip()]
        breakdowns = [field.strip() for field in str(self.breakdown_fields or "").split(",") if field.strip()]
        scored: list[dict[str, Any]] = []
        correct_counts = {field: 0 for field in targets}
        covered_counts = {field: 0 for field in targets}

        for truth_row in truth.to_dict(orient="records"):
            ticket_id = str(truth_row[id_field])
            prediction = predicted_by_id.get(ticket_id, {})
            row: dict[str, Any] = {id_field: truth_row[id_field], "prediction_received": bool(prediction)}
            for field in ("confidence", "resolution_action", "proposed_solution", "verification", "reason"):
                if field in prediction:
                    row[f"predicted_{field}"] = prediction.get(field)
            for field in breakdowns:
                if field in truth_row:
                    row[field] = truth_row.get(field)
            all_correct = bool(prediction)
            for field in targets:
                expected_key = f"_expected_{field}"
                expected = truth_row.get(expected_key, truth_row.get(field))
                actual = prediction.get(field)
                covered = actual is not None and not (isinstance(actual, float) and pd.isna(actual))
                correct = covered and self._normalize(expected) == self._normalize(actual)
                row[f"expected_{field}"] = expected
                row[f"predicted_{field}"] = actual
                row[f"correct_{field}"] = correct
                covered_counts[field] += int(covered)
                correct_counts[field] += int(correct)
                all_correct = all_correct and correct
            row["all_fields_correct"] = all_correct
            scored.append(row)

        total = len(scored)
        metrics = {
            "ticket_count": total,
            "prediction_coverage": sum(int(row["prediction_received"]) for row in scored) / total,
            "overall_exact_match": sum(int(row["all_fields_correct"]) for row in scored) / total,
            "fields": {
                field: {
                    "accuracy": correct_counts[field] / total,
                    "coverage": covered_counts[field] / total,
                    "correct": correct_counts[field],
                    "total": total,
                }
                for field in targets
            },
        }
        self._evaluation_cache = (pd.DataFrame(scored), metrics)
        return self._evaluation_cache

    def build_scored_tickets(self) -> DataFrame:
        scored, _ = self._evaluate()
        return DataFrame(scored)

    def build_resolution_decisions(self) -> DataFrame:
        scored, _ = self._evaluate()
        preferred = [
            str(self.id_field or "number").strip(),
            "predicted_support_level",
            "correct_support_level",
            "predicted_confidence",
            "predicted_resolution_action",
            "predicted_proposed_solution",
            "predicted_verification",
            "predicted_reason",
        ]
        columns = [column for column in preferred if column in scored.columns]
        return DataFrame(scored[columns].copy())

    def build_metrics(self) -> Data:
        _, metrics = self._evaluate()
        return Data(data=metrics)

    def build_summary(self) -> Message:
        _, metrics = self._evaluate()
        field_lines = ", ".join(
            f"{field}: {details['accuracy']:.1%}"
            for field, details in metrics["fields"].items()
        )
        return Message(
            text=(
                f"Know Your BAU evaluation: {metrics['ticket_count']} tickets, "
                f"{metrics['prediction_coverage']:.1%} prediction coverage, "
                f"{metrics['overall_exact_match']:.1%} all-fields exact match. "
                f"Per-field accuracy — {field_lines}."
            )
        )

from typing import Any

import pandas as pd

from lfx.custom import Component
from lfx.io import DataFrameInput, IntInput, Output, StrInput
from lfx.schema import DataFrame, Message
from lfx.schema.properties import Properties


class BAUEvaluationDashboard(Component):
    display_name = "Know Your BAU Evaluation Dashboard"
    description = "Turns scored BAU tickets into visual Markdown, performance tables, confusion data, and failure analysis."
    icon = "ChartColumnBig"
    name = "BAUEvaluationDashboard"

    inputs = [
        DataFrameInput(name="scored_tickets", display_name="Scored Tickets", required=True),
        StrInput(name="scenario_field", display_name="Scenario Breakdown Field", value="_test_scenario"),
        StrInput(name="confusion_field", display_name="Confusion Matrix Field", value="assignment_group"),
        IntInput(name="failure_limit", display_name="Maximum Failures to Show", value=20, advanced=True),
    ]

    outputs = [
        Output(display_name="Dashboard", name="dashboard", method="build_dashboard"),
        Output(display_name="Field Performance", name="field_performance", method="build_field_performance"),
        Output(display_name="Scenario Performance", name="scenario_performance", method="build_scenario_performance"),
        Output(display_name="Confusion Matrix Data", name="confusion_matrix", method="build_confusion_matrix"),
        Output(display_name="Failed Tickets", name="failed_tickets", method="build_failed_tickets"),
    ]

    @staticmethod
    def _present(value: Any) -> bool:
        if value is None:
            return False
        if isinstance(value, float) and pd.isna(value):
            return False
        return True

    @staticmethod
    def _bar(value: float, width: int = 12) -> str:
        filled = min(max(round(value * width), 0), width)
        return "█" * filled + "░" * (width - filled)

    def _analyze(self) -> dict[str, Any]:
        cached = getattr(self, "_dashboard_cache", None)
        if cached is not None:
            return cached
        frame = pd.DataFrame(self.scored_tickets).copy()
        if frame.empty:
            raise ValueError("Scored Tickets is empty.")

        correct_columns = [column for column in frame.columns if str(column).startswith("correct_")]
        if not correct_columns:
            raise ValueError("Scored Tickets has no correct_* evaluation columns.")
        fields = [str(column)[len("correct_") :] for column in correct_columns]
        total = len(frame)
        prediction_coverage = (
            float(frame["prediction_received"].fillna(False).astype(bool).mean())
            if "prediction_received" in frame.columns
            else 0.0
        )
        overall = (
            float(frame["all_fields_correct"].fillna(False).astype(bool).mean())
            if "all_fields_correct" in frame.columns
            else 0.0
        )

        field_rows: list[dict[str, Any]] = []
        for field in fields:
            correct = frame[f"correct_{field}"].fillna(False).astype(bool)
            predicted_column = f"predicted_{field}"
            if predicted_column in frame.columns:
                coverage = frame[predicted_column].map(self._present)
            else:
                coverage = pd.Series([False] * total)
            field_rows.append(
                {
                    "field": field,
                    "accuracy": float(correct.mean()),
                    "coverage": float(coverage.mean()),
                    "correct": int(correct.sum()),
                    "total": total,
                }
            )
        field_performance = pd.DataFrame(field_rows).sort_values(["accuracy", "field"]).reset_index(drop=True)

        scenario_field = str(self.scenario_field or "_test_scenario").strip()
        scenario_rows: list[dict[str, Any]] = []
        if scenario_field in frame.columns:
            scenario_values = frame[scenario_field].where(frame[scenario_field].notna(), "Unspecified")
            for scenario, group in frame.assign(_scenario_value=scenario_values).groupby("_scenario_value", dropna=False):
                scenario_rows.append(
                    {
                        "scenario": scenario,
                        "tickets": len(group),
                        "prediction_coverage": float(group["prediction_received"].fillna(False).astype(bool).mean()),
                        "all_fields_exact_match": float(group["all_fields_correct"].fillna(False).astype(bool).mean()),
                        "average_field_accuracy": float(group[correct_columns].fillna(False).astype(bool).mean(axis=1).mean()),
                    }
                )
        scenario_performance = pd.DataFrame(scenario_rows)

        confusion_field = str(self.confusion_field or "assignment_group").strip()
        expected_column = f"expected_{confusion_field}"
        predicted_column = f"predicted_{confusion_field}"
        if expected_column in frame.columns and predicted_column in frame.columns:
            confusion = (
                frame.assign(
                    expected=frame[expected_column].map(lambda value: str(value) if self._present(value) else "Missing"),
                    predicted=frame[predicted_column].map(lambda value: str(value) if self._present(value) else "Missing"),
                )
                .groupby(["expected", "predicted"], dropna=False)
                .size()
                .reset_index(name="tickets")
                .sort_values("tickets", ascending=False)
                .reset_index(drop=True)
            )
        else:
            confusion = pd.DataFrame(columns=["expected", "predicted", "tickets"])

        failures = frame.loc[~frame["all_fields_correct"].fillna(False).astype(bool)].copy()
        failure_columns = [
            column
            for column in frame.columns
            if column in {scenario_field, "prediction_received"}
            or str(column).startswith("expected_")
            or str(column).startswith("predicted_")
            or str(column).startswith("correct_")
        ]
        id_candidates = [column for column in frame.columns if column in {"number", "sys_id", "_evaluation_id"}]
        failures = failures[id_candidates + failure_columns].head(max(int(self.failure_limit), 1)).reset_index(drop=True)

        self._dashboard_cache = {
            "total": total,
            "prediction_coverage": prediction_coverage,
            "overall": overall,
            "field_performance": field_performance,
            "scenario_performance": scenario_performance,
            "confusion": confusion,
            "failures": failures,
        }
        return self._dashboard_cache

    def build_dashboard(self) -> Message:
        result = self._analyze()
        lines = [
            "# Know Your BAU Evaluation",
            "",
            "| Measure | Result | Visual |",
            "|---|---:|:---|",
            f"| Tickets evaluated | {result['total']} | |",
            f"| Prediction coverage | {result['prediction_coverage']:.1%} | `{self._bar(result['prediction_coverage'])}` |",
            f"| All-fields exact match | {result['overall']:.1%} | `{self._bar(result['overall'])}` |",
            "",
            "## Field performance",
            "",
            "| Field | Accuracy | Coverage | Accuracy bar |",
            "|---|---:|---:|:---|",
        ]
        for row in result["field_performance"].to_dict(orient="records"):
            lines.append(
                f"| {row['field']} | {row['accuracy']:.1%} | {row['coverage']:.1%} | `{self._bar(row['accuracy'])}` |"
            )
        if not result["scenario_performance"].empty:
            lines.extend(
                [
                    "",
                    "## Scenario performance",
                    "",
                    "| Scenario | Tickets | Average field accuracy | All-fields match |",
                    "|---|---:|---:|---:|",
                ]
            )
            for row in result["scenario_performance"].to_dict(orient="records"):
                lines.append(
                    f"| {row['scenario']} | {row['tickets']} | {row['average_field_accuracy']:.1%} | "
                    f"{row['all_fields_exact_match']:.1%} |"
                )
        lines.extend(
            [
                "",
                f"Failed tickets shown in the **Failed Tickets** output: {len(result['failures'])}.",
                "Use **Confusion Matrix Data** to inspect the most common routing substitutions.",
            ]
        )
        return Message(text="\n".join(lines), properties=Properties(allow_markdown=True))

    def build_field_performance(self) -> DataFrame:
        return DataFrame(self._analyze()["field_performance"])

    def build_scenario_performance(self) -> DataFrame:
        return DataFrame(self._analyze()["scenario_performance"])

    def build_confusion_matrix(self) -> DataFrame:
        return DataFrame(self._analyze()["confusion"])

    def build_failed_tickets(self) -> DataFrame:
        return DataFrame(self._analyze()["failures"])
